  function finishHTML(){const planned=Object.entries(draft.teeth||{}).filter(([,t])=>t.extractionPlan).map(([id])=>id),done=Object.values(draft.teeth||{}).filter(t=>t.extracted).length;return '<div><b>처치 요약 · '+esc(statusName(draft.clinicalStatus))+'</b><p>발치 시행 '+done+'개'+(planned.length?' · 예정으로 남은 치아 '+planned.map(id=>'<button data-finish-tooth="'+id+'">'+id+'</button>').join(' '):' · 남은 발치 예정 없음')+'</p><p>'+esc(draft.guardianDraft?guideStatus():'보호자 안내문 미작성')+(edit()?'<button data-finish-guide>'+(draft.guardianDraft?'안내문 보기':'안내문 작성')+'</button>':'')+'</p><details><summary>치아별 상세 기록</summary><div data-dn-summary>'+summary()+'</div></details></div>'+(edit()?'<button data-complete class="pt-primary" '+(busy||conflict?'disabled':'')+'>'+(draft.clinicalStatus==='complete'?'작성 중으로 변경':'작성 완료')+'</button>':'');}
