    '<details class="dn-common-meta" '+(commonMetaOpen?'open':'')+'><summary>진료 정보 · <span data-common-summary>'+esc(commonMetaSummary())+'</span> · <span data-clinical-badge>'+esc(statusName(draft.clinicalStatus))+'</span></summary><div class="dn-meta">'+field('date','진료일',draft.date,'date')+memberField('veterinarian','담당 수의사')+memberField('technician','담당 테크니션')+field('weight','기록 체중 · kg',recordWeight()??'','number')+'</div></details>'+(memberError?'<p>'+esc(memberError)+' <button data-dn="staff-retry">다시 불러오기</button></p>':'')+
    '<details class="dn-patient-details"><summary>환자정보 수정</summary><div class="dn-meta">'+(item.id&&!item.patient_id?field('patient.guardianName','보호자명',draft.patient.guardianName??item.patient.guardianName??'')+field('patient.chartNumber','차트번호',draft.patient.chartNumber??item.patient.chartNumber??''):'')+field('patient.breed','품종',draft.patient.breed)+field('patient.birthDate','생년월일',draft.patient.birthDate,'date')+'<label>성별·중성화<select data-sex><option value="unknown:unknown">미입력</option>'+[['male:no','미중성화 수컷'],['female:no','미중성화 암컷'],['male:yes','중성화 수컷'],['female:yes','중성화 암컷']].map(([v,l])=>'<option value="'+v+'" '+(draft.patient.sex+':'+draft.patient.neutered===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label></div><p class="dn-help">'+(item.patient_id?'등록 환자의 보호자명·차트번호는 환자 관리에서 수정합니다. 여기서 수정한 품종·생년월일·성별은 이 기록에만 적용됩니다.':'이 치과기록에만 적용됩니다.')+'</p></details>'+conflictHTML()+
    '<div class="dn-work" data-record-section="teeth"><section class="dn-chart-area"><div class="dn-chart-toolbar"><form class="dn-tooth-jump" data-tooth-jump><input data-tooth-number aria-label="이동할 치아 번호" inputmode="numeric" maxlength="3" placeholder="치아 번호"><button>이동</button><span data-tooth-jump-message role="status"></span></form><div class="dn-view-switch"><button data-view="teeth" aria-pressed="'+(view==='teeth')+'">치아별 보기</button><button data-view="overview" aria-pressed="'+(view==='overview')+'">전체 치열</button></div>'+(edit()?'<button data-dn="multi" aria-pressed="'+multi+'">'+(multi?'여러 치아 선택 중':'여러 치아 입력')+'</button>'+(multi?'<span data-selection-count>선택 '+picks.size+'개</span>':''):'')+'</div>'+(multi?'<div class="dn-quadrant-select">'+[[1,'상악 우측'],[2,'상악 좌측'],[4,'하악 우측'],[3,'하악 좌측']].map(([q,l])=>'<button data-quadrant="'+q+'">'+l+'</button>').join('')+'<button data-deselect>선택 해제</button></div>':'')+'<div data-undo></div>'+toothFiltersHTML()+D.typeLegend()+'<div data-chart '+(view==='overview'?'class="dn-primary-chart-hidden"':'')+'>'+D.chart(item.body.species,draft.teeth,selected)+'</div><div data-overview '+(view==='teeth'?'hidden':'')+'>'+(view==='overview'?D.overview(item.body.species,draft.teeth,selected):'')+'</div><div class="dn-state-legend">'+Object.entries(D.states).map(([k,v])=>'<span class="dn-state-'+k+'">'+esc(v)+'</span>').join('')+'</div></section><aside data-editor class="'+(editorOpen?'dn-editor-open':'')+'"></aside></div>'+
    '<div class="dn-notes dn-main-notes" data-record-section="notes">'+note('diagnosis')+note('procedure')+'</div><details class="dn-extra-notes"><summary>방사선·처방·홈케어·재검'+(['radiographs','medications','homecare','followup'].some(k=>draft[k])?' · 기록 있음':'')+'</summary><div class="dn-notes">'+['radiographs','medications','homecare','followup'].map(note).join('')+'</div></details>'+priorHTML()+extrasHTML()+'<section class="dn-finish" data-record-section="finish" data-finish>'+finishHTML()+'</section>'+
    '<details class="dn-reference"><summary>지수·치아 번호 참고</summary><p>GI 치은염 · PI 치태 · CI 치석 · PD 치주질환. 미기록은 정상 판정을 뜻하지 않습니다.</p><p>유치·과잉치는 해당 부위 메모에 기록하세요.</p><a href="https://avdc.org/avdc-nomenclature/" target="_blank" rel="noopener">AVDC 분류·치아 번호</a></details>'+(item.id&&edit()?'<div class="dn-record-actions"><button data-dn="delete" class="dn-danger">이 기록 삭제</button></div>':'');
   if(!item.id){for(const el of b.children)if(!el.matches('.dn-patient-pick,.dn-common-meta,.dn-patient-details'))el.hidden=true;}
   paintPatientSearch();chartSnapshot=copy(draft.teeth);overviewStale=view!=='overview';bindRecord();renderEditor();bindFinish();bindPrior();bindExtras();bindPhrases();updateUndo();paintValidation();if(conflict){b.querySelectorAll('input,textarea,select,button').forEach(e=>{if(!e.closest('.dn-conflict'))e.disabled=true;});bindConflict();}lockIdentity();if(!edit()){b.querySelectorAll('input,select,textarea,[data-dn=multi]').forEach(e=>{if(!e.matches('[data-prior-choice],[data-compare-all]'))e.disabled=true;});}
